"""Provider-agnostic API client for ARIA."""

import json
import logging
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

try:
    import google.generativeai as genai
except ModuleNotFoundError:
    genai = None

logger = logging.getLogger(__name__)


@dataclass
class APIConfig:
    api_key: str
    model: str = "gemma-4-26b-a4b-it"
    temperature: float = 0.7
    max_tokens: int = 8192
    provider: str = "google"
    timeout: int = 60


class ProviderError(RuntimeError):
    def __init__(self, message: str, retryable: bool = False, status: Optional[int] = None):
        super().__init__(message)
        self.retryable = retryable
        self.status = status


class BaseProvider:
    name = "base"

    def list_models(self) -> List[str]:
        raise NotImplementedError

    def generate(self, prompt: str, system_instruction: Optional[str], config: APIConfig) -> str:
        raise NotImplementedError


class GoogleProvider(BaseProvider):
    name = "google"

    def __init__(self, api_key: str):
        if genai is None:
            raise ProviderError(
                "Google provider requires `google-generativeai`. "
                "Install with: pip install google-generativeai --break-system-packages",
                retryable=False,
            )
        self.api_key = api_key
        genai.configure(api_key=api_key)

    def list_models(self) -> List[str]:
        try:
            models = genai.list_models()
            return [m.name.replace("models/", "") for m in models]
        except Exception as e:
            raise ProviderError(f"Google model list failed: {e}", retryable=False) from e

    def generate(self, prompt: str, system_instruction: Optional[str], config: APIConfig) -> str:
        try:
            model = genai.GenerativeModel(
                model_name=config.model,
                system_instruction=system_instruction,
                generation_config=genai.types.GenerationConfig(
                    temperature=config.temperature,
                    max_output_tokens=config.max_tokens,
                ),
            )
            response = model.generate_content(prompt)
            text = getattr(response, "text", None)
            if not text:
                raise ProviderError("Google returned an empty/malformed response", retryable=True)
            return text
        except Exception as e:
            msg = str(e).lower()
            retryable = any(k in msg for k in ("timeout", "tempor", "429", "quota", "unavailable"))
            raise ProviderError(f"Google request failed: {e}", retryable=retryable) from e


class GoogleRESTProvider(BaseProvider):
    """Google AI Studio over plain HTTPS, stdlib only.

    Used when `google-generativeai` isn't installed (it often can't be on
    Termux). Talks to the same Gemini API the SDK wraps.
    """

    name = "google"
    BASE_URL = "https://generativelanguage.googleapis.com/v1beta"

    def __init__(self, api_key: str):
        self.api_key = api_key

    @staticmethod
    def _error_message(body: str) -> str:
        try:
            msg = json.loads(body).get("error", {}).get("message")
            if msg:
                return str(msg)[:180]
        except (ValueError, AttributeError):
            pass
        return body[:180]

    def _request_json(
        self,
        method: str,
        path: str,
        payload: Optional[Dict[str, Any]] = None,
        timeout: int = 60,
    ) -> Dict[str, Any]:
        url = f"{self.BASE_URL}{path}"
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        # Key goes in a header, not the URL, so it can't leak into error messages or logs.
        headers = {"x-goog-api-key": self.api_key, "Content-Type": "application/json"}
        req = urllib.request.Request(url, method=method, data=data, headers=headers)

        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="replace")
            lowered = body.lower()
            if e.code in (401, 403) or "api key not valid" in lowered or "api_key_invalid" in lowered:
                raise ProviderError("google auth failed (invalid API key)", retryable=False, status=e.code)
            if e.code == 404:
                raise ProviderError("google model/API route unavailable", retryable=False, status=404)
            if e.code == 429:
                raise ProviderError("google rate limit reached", retryable=True, status=429)
            if 500 <= e.code <= 599:
                raise ProviderError(f"google provider downtime/server error ({e.code})", retryable=True, status=e.code)
            raise ProviderError(
                f"google HTTP {e.code}: {self._error_message(body)}", retryable=False, status=e.code
            )
        except urllib.error.URLError as e:
            raise ProviderError(f"google network error: {e}", retryable=True) from e
        except json.JSONDecodeError as e:
            raise ProviderError(f"google returned malformed JSON: {e}", retryable=True) from e
        except Exception as e:
            raise ProviderError(f"google unexpected failure: {e}", retryable=True) from e

    def list_models(self) -> List[str]:
        models: List[str] = []
        page_token = ""
        for _ in range(10):  # hard cap on pagination
            path = "/models?pageSize=1000"
            if page_token:
                path += "&pageToken=" + urllib.parse.quote(page_token, safe="")
            data = self._request_json("GET", path)
            for item in data.get("models", []):
                name = item.get("name", "")
                methods = item.get("supportedGenerationMethods")
                if name and (methods is None or "generateContent" in methods):
                    models.append(name.replace("models/", "", 1))
            page_token = data.get("nextPageToken", "")
            if not page_token:
                break
        if not models:
            raise ProviderError("google returned no models", retryable=False)
        return models

    def generate(self, prompt: str, system_instruction: Optional[str], config: APIConfig) -> str:
        model = config.model.strip()
        if model.startswith("models/"):
            model = model[len("models/"):]
        path = f"/models/{urllib.parse.quote(model, safe='')}:generateContent"

        payload: Dict[str, Any] = {
            "contents": [{"role": "user", "parts": [{"text": prompt}]}],
            "generationConfig": {
                "temperature": config.temperature,
                "maxOutputTokens": config.max_tokens,
            },
        }
        if system_instruction:
            payload["systemInstruction"] = {"parts": [{"text": system_instruction}]}

        try:
            data = self._request_json("POST", path, payload=payload, timeout=config.timeout)
        except ProviderError as e:
            # Some models (e.g. Gemma) reject a separate system instruction;
            # retry once with it folded into the prompt.
            if system_instruction and e.status == 400 and "instruction" in str(e).lower():
                payload.pop("systemInstruction")
                payload["contents"][0]["parts"][0]["text"] = f"{system_instruction}\n\n{prompt}"
                data = self._request_json("POST", path, payload=payload, timeout=config.timeout)
            else:
                raise
        return self._extract_text(data)

    @staticmethod
    def _extract_text(data: Dict[str, Any]) -> str:
        candidates = data.get("candidates") or []
        if candidates:
            parts = (candidates[0].get("content") or {}).get("parts") or []
            text = "".join(p.get("text", "") for p in parts if not p.get("thought"))
            if text:
                return text
        block = (data.get("promptFeedback") or {}).get("blockReason")
        if block:
            raise ProviderError(f"google blocked the prompt ({block})", retryable=False)
        raise ProviderError("google returned an empty/malformed response", retryable=True)


class OpenAICompatProvider(BaseProvider):
    """Provider for OpenRouter and NVIDIA NIM using OpenAI-compatible chat API."""

    def __init__(self, name: str, api_key: str, base_url: str, extra_headers: Optional[Dict[str, str]] = None):
        self.name = name
        self.api_key = api_key
        self.base_url = base_url.rstrip("/")
        self.extra_headers = extra_headers or {}

    def _request_json(
        self,
        method: str,
        path: str,
        payload: Optional[Dict[str, Any]] = None,
        timeout: int = 60,
    ) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        headers.update(self.extra_headers)
        req = urllib.request.Request(url, method=method, data=data, headers=headers)

        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="replace")
            lowered = body.lower()
            if e.code in (401, 403):
                raise ProviderError(f"{self.name} auth failed (invalid API key)", retryable=False)
            if e.code == 404:
                raise ProviderError(f"{self.name} model/API route unavailable", retryable=False)
            if e.code == 429:
                raise ProviderError(f"{self.name} rate limit reached", retryable=True)
            if 500 <= e.code <= 599:
                raise ProviderError(f"{self.name} provider downtime/server error ({e.code})", retryable=True)
            raise ProviderError(f"{self.name} HTTP {e.code}: {body[:180]}", retryable=("timeout" in lowered))
        except urllib.error.URLError as e:
            raise ProviderError(f"{self.name} network error: {e}", retryable=True) from e
        except json.JSONDecodeError as e:
            raise ProviderError(f"{self.name} returned malformed JSON: {e}", retryable=True) from e
        except Exception as e:
            raise ProviderError(f"{self.name} unexpected failure: {e}", retryable=True) from e

    def list_models(self) -> List[str]:
        data = self._request_json("GET", "/models")
        models: List[str] = []
        for item in data.get("data", []):
            model_id = item.get("id")
            if model_id:
                models.append(model_id)
        if not models:
            raise ProviderError(f"{self.name} returned no models", retryable=False)
        return models

    def generate(self, prompt: str, system_instruction: Optional[str], config: APIConfig) -> str:
        messages: List[Dict[str, str]] = []
        if system_instruction:
            messages.append({"role": "system", "content": system_instruction})
        messages.append({"role": "user", "content": prompt})

        payload = {
            "model": config.model,
            "messages": messages,
            "temperature": config.temperature,
            "max_tokens": config.max_tokens,
            "stream": False,  # Force non-stream for reliability
        }
        data = self._request_json("POST", "/chat/completions", payload=payload, timeout=config.timeout)
        try:
            return data["choices"][0]["message"]["content"]
        except (KeyError, IndexError, TypeError) as e:
            raise ProviderError(f"{self.name} malformed completion payload", retryable=True) from e

    # Streaming removed: non-stream mode is more reliable for Termux
    # and eliminates the "infinite thinking" spinner issue.


class APIClient:
    SUPPORTED_PROVIDERS: Dict[str, str] = {
        "google": "Google AI Studio",
        "openrouter": "OpenRouter",
        "nvidia_nim": "NVIDIA NIM",
    }

    def __init__(self, config: APIConfig):
        self.config = config
        self.available_models: List[str] = []
        self.last_error: Optional[str] = None
        self._provider: Optional[BaseProvider] = None
        self._initialize_provider()

    def _initialize_provider(self):
        p = self.config.provider.lower().strip()
        key = (self.config.api_key or "").strip()
        if not key:
            raise ValueError(f"No API key configured for provider '{p}'")
        try:
            if p == "google":
                # Prefer the SDK when present; otherwise talk to the API directly.
                self._provider = GoogleProvider(key) if genai is not None else GoogleRESTProvider(key)
            elif p == "openrouter":
                self._provider = OpenAICompatProvider(
                    name="OpenRouter",
                    api_key=key,
                    base_url="https://openrouter.ai/api/v1",
                    extra_headers={"HTTP-Referer": "https://termux.dev", "X-Title": "ARIA-Termux"},
                )
            elif p == "nvidia_nim":
                self._provider = OpenAICompatProvider(
                    name="NVIDIA NIM",
                    api_key=key,
                    base_url="https://integrate.api.nvidia.com/v1",
                )
            else:
                raise ValueError(f"Unsupported provider: {self.config.provider}")
            logger.info(f"API provider initialized: {p} model={self.config.model}")
        except ProviderError as e:
            self._provider = None
            self.last_error = str(e)
            logger.error(f"API provider unavailable: {e}")

    def get_supported_providers(self) -> Dict[str, str]:
        return dict(self.SUPPORTED_PROVIDERS)

    def fetch_available_models(self) -> List[str]:
        try:
            self.available_models = self._provider.list_models() if self._provider else []
            self.last_error = None
            return self.available_models
        except ProviderError as e:
            self.last_error = str(e)
            logger.error(self.last_error)
            return self.available_models[:]

    def validate_model(self, model: str) -> bool:
        if not self.available_models:
            self.fetch_available_models()
        return model in self.available_models if self.available_models else True

    def generate_content(self, prompt: str, system_instruction: Optional[str] = None, max_retries: int = 3) -> str:
        if not self._provider:
            return self._get_fallback_response()

        validated = self.validate_model(self.config.model)
        if not validated and self.available_models:
            old = self.config.model
            self.config.model = self.available_models[0]
            logger.warning(f"Model '{old}' unavailable; switched to '{self.config.model}'")

        for attempt in range(max_retries):
            try:
                text = self._provider.generate(prompt, system_instruction, self.config)
                self.last_error = None
                return text
            except ProviderError as e:
                self.last_error = str(e)
                logger.warning(f"Provider attempt {attempt + 1}/{max_retries} failed: {e}")
                if attempt >= max_retries - 1 or not e.retryable:
                    break
                time.sleep(min(4, 2 ** attempt))
            except Exception as e:
                self.last_error = str(e)
                logger.warning(f"Unexpected attempt failure {attempt + 1}/{max_retries}: {e}")
                if attempt >= max_retries - 1:
                    break
                time.sleep(min(4, 2 ** attempt))
        return self._get_fallback_response()

    def _get_fallback_response(self) -> str:
        return (
            f"API Error ({self.config.provider}/{self.config.model}): {self.last_error}\n\n"
            "Fallback: offline mode is active; use `/kb <query>` for offline help.\n"
            "Try `/provider list`, `/provider set <name>`, `/model list`, or `/config`."
        )

    def is_available(self) -> bool:
        return bool(self.fetch_available_models())

    def validate_key(self, timeout: int = 10) -> tuple:
        """Quick health-check: verify the API key works with a minimal request.
        Returns (success: bool, message: str)."""
        if not self._provider:
            return False, "No provider initialized"
        try:
            if isinstance(self._provider, (GoogleProvider, GoogleRESTProvider)):
                # Minimal call: list models (lightweight, requires valid key)
                self._provider.list_models()
            else:
                # For OpenAI-compat: send a tiny completion request (1 token)
                # This actually validates the key unlike /models which is public
                payload = {
                    "model": self.config.model or "openrouter/auto",
                    "messages": [{"role": "user", "content": "hi"}],
                    "max_tokens": 1,
                }
                self._provider._request_json(
                    "POST", "/chat/completions", payload=payload, timeout=timeout
                )
            return True, f"{self.config.provider} API key is valid"
        except ProviderError as e:
            msg = str(e)
            # If it's a model-not-found error but auth passed, key is valid
            if "404" in msg or "not found" in msg.lower() or "unavailable" in msg.lower():
                return True, f"{self.config.provider} key accepted (model may need updating)"
            return False, msg
        except Exception as e:
            return False, f"Validation failed: {e}"

